#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int issq(long long v){long long r=0;while(r*r<v)r++;return r*r==v;}int main(void){int n,i;static long long a[500005];if(scanf("%d",&n)!=1)return 1;for(i=0;i<n;i++)scanf("%lld",&a[i]);int ok=0;for(i=0;i<n;i++){long long x=a[i];if(issq(x)){ok=1;break;}}printf("%s\n",ok?"YES":"NO");return 0;}
